function LayerBadges({ layers }: { layers: string[] }) {
  return <div className="flex flex-wrap gap-1.5">{['BL','ML','UL','TL'].map((item) => <span key={item} className={`rounded-full px-2.5 py-1 text-xs font-semibold ${layers.includes(item) ? 'bg-primary text-primary-foreground' : item === 'TL' ? 'border border-dashed border-border text-muted-foreground' : 'bg-secondary text-muted-foreground'}`}>{item}</span>)}</div>;
}

export function RegulationsWorkbench({ regulations, details, onOpenRegulation }: { regulations: Regulation[]; details: Record<number, RegulationDetail>; onOpenRegulation: (regulation: Regulation) => void }) {
  const [view, setView] = useState<'start'|'course'|'study'|'library'|'regulation'>('start');
  const [moduleIndex, setModuleIndex] = useState(0);
  const [step, setStep] = useState('overview');
  const [activeLayer, setActiveLayer] = useState<keyof typeof layerCopy>('BL');
  const [type, setType] = useState('NBFC-ICC');
  const [asset, setAsset] = useState('');
  const [deposit, setDeposit] = useState('No');
  const [customer, setCustomer] = useState('Yes');
  const [publicFunds, setPublicFunds] = useState('Not known');
  const [libraryQuery, setLibraryQuery] = useState('');
  const [libraryLayer, setLibraryLayer] = useState('All');
  const [selectedRegulationId, setSelectedRegulationId] = useState(1);
  const [detailSection, setDetailSection] = useState<'meaning'|'applicability'|'rules'|'example'|'source'>('meaning');
  const selectedModule = syllabus[moduleIndex];
  const selectedRegulation = regulations.find((item) => item.id === selectedRegulationId) ?? regulations[0];
  const selectedDetail = selectedRegulation ? details[selectedRegulation.id] : undefined;
  const layerGuide = selectedRegulation ? getLayerGuide(selectedRegulation.id) : null;
  const library = useMemo(() => regulations.filter((regulation) => {
    const text = `${regulation.title} ${regulation.category} ${regulation.summary}`.toLowerCase();
    return (!libraryQuery || text.includes(libraryQuery.toLowerCase())) && (libraryLayer === 'All' || regulation.layers.includes(libraryLayer));
  }), [regulations, libraryQuery, libraryLayer]);
  const likelyLayer = deposit === 'Yes' ? 'ML or UL' : asset && Number(asset) >= 1000 ? 'ML or UL' : ['NBFC-P2P','Account Aggregator'].includes(type) ? 'BL' : 'BL, subject to category and group tests';

  const openStudy = (next = 'overview') => { setStep(next); setView('study'); };
  const openRegulation = (regulation: Regulation) => { setSelectedRegulationId(regulation.id); setDetailSection('meaning'); setView('regulation'); document.getElementById('workbench')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); };

  return <section className="space-y-6">
    <div className="flex flex-wrap gap-2 rounded-2xl border border-border bg-card p-2">
      {([['start','Start here'],['course','21-module course'],['study','Study SBR'],['library',`Master library · ${regulations.length}`],...(view === 'regulation' ? [['regulation', selectedRegulation?.short ?? 'Regulation']] : [])] as [typeof view,string][]).map(([key,label]) => <button type="button" key={key} onClick={() => setView(key)} className={`rounded-xl px-4 py-2.5 text-sm font-semibold ${view === key ? 'bg-primary text-primary-foreground' : 'hover:bg-secondary'}`}>{label}</button>)}
    </div>

    {view === 'start' && <div className="overflow-hidden rounded-3xl border border-slate-800 bg-[#07182b] text-white">
      <div className="grid gap-8 p-6 sm:p-9 lg:grid-cols-[1.15fr_.85fr]">
        <div><p className="text-xs font-semibold uppercase tracking-[.18em] text-cyan-200">Regulatory law library + course</p><h2 className="mt-3 max-w-3xl text-3xl font-semibold tracking-[-.04em] sm:text-4xl">Find the rule. Test who it applies to. Reach the exact RBI source.</h2><p className="mt-4 max-w-3xl text-base leading-7 text-slate-300">Learn how NBFC law is organised, then study each indexed direction through applicability, operative rule, trigger, threshold, exception, amendment and source.</p><div className="mt-6 flex flex-wrap gap-3"><Button className="bg-cyan-200 text-slate-950 hover:bg-cyan-100" onClick={() => setView('course')}>Begin the regulatory course<ArrowRight /></Button><Button variant="outline" className="border-white/20 bg-white/5 text-white hover:bg-white/10" onClick={() => openStudy()}>Study Scale Based Regulation</Button></div></div>
        <div className="grid grid-cols-2 gap-3"><div className="rounded-2xl border border-white/10 bg-white/[.06] p-5"><p className="text-3xl font-semibold">28</p><p className="mt-1 text-sm text-slate-300">indexed source documents</p></div><div className="rounded-2xl border border-white/10 bg-white/[.06] p-5"><p className="text-3xl font-semibold">21</p><p className="mt-1 text-sm text-slate-300">connected study modules</p></div><div className="col-span-2 rounded-2xl border border-cyan-200/20 bg-cyan-200/10 p-5"><p className="text-xs font-semibold uppercase tracking-[.14em] text-cyan-200">Latest indexed consolidation</p><p className="mt-2 text-xl font-semibold">01 July 2026</p><p className="mt-1 text-sm leading-6 text-slate-300">Registration/SBR source copy. Dates describe the uploaded library, not an assurance that no later RBI material exists.</p></div></div>
      </div>
      <div className="border-t border-white/10 bg-white/[.035] p-6 sm:p-9"><p className="text-xs font-semibold uppercase tracking-[.15em] text-cyan-200">Use the five-question legal test</p><div className="mt-4 grid gap-3 md:grid-cols-5">{['What is the rule?','Who does it apply to?','Which paragraph says it?','Effective from when?','Has it been amended?'].map((item,index) => <div key={item} className="rounded-xl border border-white/10 bg-white/[.04] p-4"><span className="font-mono text-xs text-cyan-200">0{index+1}</span><p className="mt-2 text-sm font-semibold leading-5">{item}</p></div>)}</div></div>
    </div>}

    {view === 'course' && <div className="grid gap-5 xl:grid-cols-[330px_minmax(0,1fr)]">
      <aside className="rounded-3xl border border-border bg-card p-4"><div className="border-b border-border p-2 pb-4"><p className="eyebrow">Regulations syllabus</p><h3 className="mt-1 text-xl font-semibold">21 connected modules</h3></div><div className="mt-3 max-h-[760px] space-y-1 overflow-y-auto">{syllabus.map((module,index) => <button type="button" key={module[0]} onClick={() => setModuleIndex(index)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left ${moduleIndex === index ? 'bg-primary text-primary-foreground' : 'hover:bg-secondary'}`}><span className={`grid size-8 shrink-0 place-items-center rounded-lg font-mono text-xs font-semibold ${moduleIndex === index ? 'bg-white/15' : 'bg-primary/10 text-primary'}`}>{String(index+1).padStart(2,'0')}</span><span className="text-sm font-semibold leading-5">{module[0]}</span></button>)}</div></aside>
      <article className="overflow-hidden rounded-3xl border border-border bg-card"><header className="bg-[#07182b] p-6 text-white sm:p-8"><Badge className="bg-cyan-200 text-slate-950">Module {String(moduleIndex+1).padStart(2,'0')}</Badge><h3 className="mt-5 text-3xl font-semibold tracking-[-.035em]">{selectedModule[0]}</h3><p className="mt-3 max-w-3xl text-base leading-7 text-slate-300">{selectedModule[1]}</p></header><div className="space-y-7 p-6 sm:p-8"><section><p className="eyebrow">How to study this module</p><div className="mt-4 grid gap-3 md:grid-cols-3">{[['Start with applicability','Identify entity, layer, category and activity.'],['Read the operative rule','Separate the legal text from explanation and examples.'],['Close with authority','Record paragraph, date, amendment and exception.']].map(([title,body],index) => <div key={title} className="rounded-2xl border border-border bg-secondary/25 p-4"><span className="font-mono text-xs font-semibold text-primary">0{index+1}</span><p className="mt-2 font-semibold">{title}</p><p className="mt-1 text-sm leading-6 text-muted-foreground">{body}</p></div>)}</div></section><section className="rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="eyebrow text-blue-800">Governing materials in this desk</p><div className="mt-3 flex flex-wrap gap-2">{selectedModule[2].length ? selectedModule[2].map((id) => { const reg = regulations.find((item) => item.id === id); return reg ? <Button key={id} variant="outline" className="border-blue-300 bg-white text-blue-950" onClick={() => openRegulation(reg)}>{reg.short}<ChevronRight /></Button> : null; }) : <Button onClick={() => setView('library')}>Open all {regulations.length} indexed sources<ArrowRight /></Button>}</div></section>{moduleIndex === 2 && <Button onClick={() => openStudy()}>Open the complete SBR study page<ArrowRight /></Button>}<footer className="flex items-center justify-between border-t border-border pt-5"><Button variant="outline" disabled={moduleIndex === 0} onClick={() => setModuleIndex((value) => Math.max(0,value-1))}>Previous</Button><p className="text-sm font-semibold text-muted-foreground">Module {moduleIndex+1} of {syllabus.length}</p><Button disabled={moduleIndex === syllabus.length-1} onClick={() => setModuleIndex((value) => Math.min(syllabus.length-1,value+1))}>Next<ArrowRight /></Button></footer></div></article>
    </div>}

    {view === 'study' && <div className="grid gap-5 xl:grid-cols-[270px_minmax(0,1fr)]">
      <aside className="self-start rounded-3xl border border-border bg-card p-4 xl:sticky xl:top-24"><p className="eyebrow px-2">Study a regulation</p><h3 className="px-2 pt-1 text-lg font-semibold">Scale Based Regulation</h3><div className="mt-4 max-h-[70vh] space-y-1 overflow-y-auto">{studySteps.map(([key,label],index) => <button type="button" key={key} onClick={() => setStep(key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold ${step === key ? 'bg-primary text-primary-foreground' : 'hover:bg-secondary'}`}><span className="font-mono text-xs opacity-70">{String(index+1).padStart(2,'0')}</span>{label}</button>)}</div></aside>
      <article className="min-w-0 overflow-hidden rounded-3xl border border-border bg-card">
        <header className="bg-[#07182b] p-6 text-white sm:p-8"><div className="flex flex-wrap gap-2"><Badge className="bg-cyan-200 text-slate-950">RBI · SBR Framework</Badge><Badge variant="outline" className="border-white/20 text-white">Current indexed copy · 01 Jul 2026</Badge></div><h2 className="mt-5 max-w-4xl text-3xl font-semibold tracking-[-.04em] sm:text-4xl">Scale Based Regulation for NBFCs</h2><p className="mt-4 max-w-3xl text-base leading-7 text-slate-300">A progressive study of what the framework does, where an NBFC falls, what changes by layer and which RBI paragraph supports the conclusion.</p></header>
        <div className="space-y-7 p-6 sm:p-8">
          {step === 'overview' && <><section><p className="eyebrow">What is Scale Based Regulation?</p><p className="mt-3 text-lg leading-8">SBR places NBFCs into four layers and increases regulatory intensity as size, activity, complexity and perceived risk increase. It is a classification gateway: first identify the layer, then read the prudential, governance and conduct directions that use that layer.</p></section><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{[['Regulatory objective','Proportionate regulation and closer supervision of higher-risk NBFCs'],['Regulator','Reserve Bank of India'],['Area','Registration, classification and regulatory intensity'],['Introduced','RBI SBR framework introduced in 2021'],['Primary indexed source','NBFC – Registration, Exemptions and Framework for SBR Directions, 2025'],['Latest indexed update','Consolidated as on 01 July 2026']].map(([title,body]) => <div key={title} className="rounded-2xl border border-border bg-secondary/25 p-4"><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">{title}</p><p className="mt-2 text-sm font-semibold leading-6">{body}</p></div>)}</div><section className="rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="font-semibold text-blue-950">Why RBI introduced it</p><p className="mt-2 text-sm leading-7 text-blue-950">A small, narrowly connected NBFC does not present the same financial-system risk as a very large, complex or interconnected NBFC. SBR lets RBI use a common foundation while adding stricter requirements and supervisory attention as risk grows.</p><a href={registrationSecondAmendmentUrl} target="_blank" rel="noreferrer" className="mt-4 inline-flex items-center gap-2 text-sm font-semibold text-blue-900 hover:underline">View RBI Second Amendment notification<ArrowRight className="size-4" /></a></section></>}
          {step === 'layers' && <><section><p className="eyebrow">Understand the four-layer structure</p><h3 className="mt-1 text-2xl font-semibold">Select a layer to understand its role</h3><div className="mt-5 grid gap-2 sm:grid-cols-4">{(Object.keys(layerCopy) as (keyof typeof layerCopy)[]).map((key,index) => <button type="button" key={key} onClick={() => setActiveLayer(key)} className={`rounded-2xl border p-4 text-left ${activeLayer === key ? 'border-primary bg-primary text-primary-foreground' : 'border-border hover:border-primary/30'}`}><span className="font-mono text-xs">0{index+1}</span><p className="mt-2 font-semibold">{layerCopy[key].name}</p><p className="mt-1 text-xs opacity-75">{key}</p></button>)}</div></section><section className="rounded-3xl border border-primary/20 bg-primary/[.045] p-6"><div className="flex items-center justify-between"><div><p className="eyebrow text-primary">{activeLayer}</p><h3 className="mt-1 text-2xl font-semibold">{layerCopy[activeLayer].name}</h3></div><Layers3 className="size-8 text-primary" /></div><p className="mt-4 text-lg leading-8">{layerCopy[activeLayer].result}</p><div className="mt-5 grid gap-4 md:grid-cols-2"><div><p className="text-sm font-semibold">Who may fall here?</p><p className="mt-2 text-sm leading-6 text-muted-foreground">{layerCopy[activeLayer].who}</p></div><div><p className="text-sm font-semibold">Source anchor</p><p className="mt-2 text-sm leading-6 text-primary">{layerCopy[activeLayer].source}</p></div></div></section><aside className="rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm leading-6 text-amber-950"><strong>Important:</strong> do not assume every BL rule automatically applies upward, or every ML rule applies to UL. Read the applicability and operative provision of each direction.</aside></>}
          {step === 'classify' && <><section><p className="eyebrow">Who falls where?</p><h3 className="mt-1 text-2xl font-semibold">Build a preliminary classification profile</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">This is a research starting point, not a final legal classification.</p></section><div className="grid gap-4 md:grid-cols-2"><label className="text-sm font-semibold">NBFC type<NativeSelect value={type} onChange={(event) => setType(event.target.value)} className="mt-2 w-full">{['NBFC-ICC','NBFC-MFI','NBFC-Factor','IFC','CIC','NBFC-P2P','Account Aggregator','HFC'].map((item) => <NativeSelectOption key={item} value={item}>{item}</NativeSelectOption>)}</NativeSelect></label><label className="text-sm font-semibold">Asset size (₹ crore)<Input value={asset} onChange={(event) => setAsset(event.target.value)} type="number" min="0" className="mt-2" placeholder="Enter if known" /></label><label className="text-sm font-semibold">Deposit taking?<NativeSelect value={deposit} onChange={(event) => setDeposit(event.target.value)} className="mt-2 w-full"><NativeSelectOption value="No">No</NativeSelectOption><NativeSelectOption value="Yes">Yes</NativeSelectOption></NativeSelect></label><label className="text-sm font-semibold">Customer interface?<NativeSelect value={customer} onChange={(event) => setCustomer(event.target.value)} className="mt-2 w-full"><NativeSelectOption value="Yes">Yes</NativeSelectOption><NativeSelectOption value="No">No</NativeSelectOption></NativeSelect></label><label className="text-sm font-semibold">Public funds?<NativeSelect value={publicFunds} onChange={(event) => setPublicFunds(event.target.value)} className="mt-2 w-full"><NativeSelectOption value="Not known">Not known</NativeSelectOption><NativeSelectOption value="Yes">Yes</NativeSelectOption><NativeSelectOption value="No">No</NativeSelectOption></NativeSelect></label></div><section className="rounded-2xl border border-primary/20 bg-primary/[.045] p-5"><p className="eyebrow text-primary">Preliminary reading path</p><p className="mt-2 text-xl font-semibold">Examine: {likelyLayer}</p><p className="mt-3 text-sm leading-6">Why: deposit status, audited/group assets and category placement affect the layer. Customer interface and public funds may also change the applicability of particular directions. Confirm group aggregation, exact category and any RBI identification before concluding.</p></section></>}
          {step === 'map' && <><section><p className="eyebrow">Regulation map</p><h3 className="mt-1 text-2xl font-semibold">Follow SBR into the subject rulebooks</h3></section><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{[['Entry & registration',1],['Capital',2],['Prudential / IRACP',3],['Concentration / exposure',5],['Governance',10],['Risk management',26],['Customer conduct',7],['Disclosure',13],['Reporting',12]].map(([label,id],index) => { const reg=regulations.find((item)=>item.id===id); return reg ? <button type="button" key={String(label)} onClick={() => openRegulation(reg)} className="group flex items-center gap-4 rounded-2xl border border-border p-4 text-left hover:border-primary/30 hover:bg-secondary/30"><span className="grid size-9 shrink-0 place-items-center rounded-xl bg-primary/10 font-mono text-xs font-semibold text-primary">{String(index+1).padStart(2,'0')}</span><span className="font-semibold">{label}</span><ChevronRight className="ml-auto size-4 transition-transform group-hover:translate-x-1" /></button> : null; })}</div></>}
          {step === 'concepts' && <><section><p className="eyebrow">Know these first</p><h3 className="mt-1 text-2xl font-semibold">Five concepts that unlock the framework</h3></section><div className="grid gap-4 md:grid-cols-2">{concepts.map(([term,meaning,why,example]) => <details key={term} className="rounded-2xl border border-border p-5 open:bg-secondary/20"><summary className="cursor-pointer font-semibold text-primary">{term}</summary><p className="mt-4 text-sm leading-6"><strong>Meaning:</strong> {meaning}</p><p className="mt-2 text-sm leading-6"><strong>Why it matters:</strong> {why}</p><p className="mt-2 text-sm leading-6 text-muted-foreground"><strong>Example:</strong> {example}</p></details>)}</div></>}
          {step === 'subjects' && <><section><p className="eyebrow">Study by regulatory subject</p><h3 className="mt-1 text-2xl font-semibold">Every requirement follows the same legal-reading structure</h3></section><div className="space-y-3">{sbrSubjects.map((subject) => <details key={subject.name} className="rounded-2xl border border-border bg-card p-5 open:border-primary/25"><summary className="flex cursor-pointer list-none items-center justify-between gap-4"><span className="text-lg font-semibold">{subject.name}</span><LayerBadges layers={['BL','ML','UL']} /></summary><div className="mt-5 grid gap-4 md:grid-cols-2"><div><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">A · What is this about?</p><p className="mt-2 text-sm leading-6">{subject.about}</p></div><div><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">B · What does RBI require?</p><p className="mt-2 text-sm leading-6">{subject.rule}</p></div><div><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">C · Why?</p><p className="mt-2 text-sm leading-6">{subject.reason}</p></div><div><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">E–F · Trigger / threshold</p><p className="mt-2 text-sm leading-6">{subject.trigger} {subject.threshold}</p></div></div><div className="mt-5 rounded-xl border border-blue-200 bg-blue-50 p-4 text-sm font-semibold leading-6 text-blue-950">RBI source: {subject.source}</div></details>)}</div></>}
          {step === 'compare' && <><section><p className="eyebrow">What changes by layer?</p><h3 className="mt-1 text-2xl font-semibold">Compare the difference—not three copies of the same rule</h3></section><div className="overflow-x-auto rounded-2xl border border-border"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-[#07182b] text-white"><tr><th className="p-4">Subject</th><th className="p-4">Base Layer</th><th className="p-4">Middle Layer</th><th className="p-4">Upper Layer</th></tr></thead><tbody>{[['Classification','Lower-intensity starting layer; category placement still matters.','₹1,000 crore main size entry plus deposit/category/group tests.','Separate UL test / RBI identification; verify indexed paragraph 12 and 24.'],['Capital','No universal ML+ formulation; category-specific provisions can apply.','General 15% CRAR and 10% Tier 1 in the indexed capital direction.','ML minima plus 9% CET1 in the indexed capital direction.'],['Concentration','Board/internal limits or BL chapter, subject to conditions.','Quantitative exposure framework for covered ML entities.','Separate large-exposure framework and heightened oversight.'],['Governance','Baseline governance mapped to category and activity.','Additional committees/control functions triggered by size and layer.','Heightened governance, succession and listing-related consequences.']].map((row)=><tr key={row[0]} className="border-t border-border align-top"><th className="p-4 font-semibold">{row[0]}</th><td className="p-4 leading-6">{row[1]}</td><td className="p-4 leading-6">{row[2]}</td><td className="p-4 leading-6">{row[3]}</td></tr>)}</tbody></table></div><p className="text-xs leading-5 text-muted-foreground">These are study pointers. Open the relevant direction for its exact applicability clause, category exclusions and amendment position.</p></>}
          {step === 'matrix' && <><section><p className="eyebrow">Requirements matrix</p><h3 className="mt-1 text-2xl font-semibold">Trace requirement → layer → trigger → source</h3></section><div className="overflow-x-auto rounded-2xl border border-border"><table className="w-full min-w-[920px] text-left text-sm"><thead className="bg-secondary"><tr>{['Requirement','BL','ML','UL','Trigger / threshold','RBI source'].map((item)=><th key={item} className="p-4">{item}</th>)}</tr></thead><tbody>{sbrSubjects.map((subject)=><tr key={subject.name} className="border-t border-border align-top"><th className="p-4 font-semibold">{subject.name}</th>{subject.layers.slice(0,3).map((mark,index)=><td key={index} className="p-4 text-lg font-semibold text-primary">{mark}</td>)}<td className="p-4 leading-6">{subject.trigger} {subject.threshold}</td><td className="p-4 leading-6 text-primary">{subject.source}</td></tr>)}</tbody></table></div><p className="text-xs text-muted-foreground">✓ Applicable · — Not applicable · △ Conditional. A conditional mark requires the category, activity, threshold and exception to be checked.</p></>}
          {step === 'lens' && <><section><p className="eyebrow">View this regulation as my NBFC</p><h3 className="mt-1 text-2xl font-semibold">Use the same profile in a rule-by-rule lens</h3></section><div className="grid gap-4 md:grid-cols-3">{[['Applicable to your profile','Registration/perimeter analysis; KYC and conduct if customer-facing.'],['Conditionally applicable',`SBR placement: ${likelyLayer}. Capital, concentration, ALM and governance depend on the confirmed layer/category.`],['Needs more information','Audited and group asset size, precise category, public-funds position and any RBI identification.']].map(([title,body],index)=><div key={title} className={`rounded-2xl border p-5 ${index===0?'border-emerald-200 bg-emerald-50':index===1?'border-amber-200 bg-amber-50':'border-blue-200 bg-blue-50'}`}><p className="font-semibold">{title}</p><p className="mt-2 text-sm leading-6">{body}</p></div>)}</div><Button variant="outline" onClick={() => setStep('classify')}>Edit classification inputs</Button></>}
          {step === 'thresholds' && <><section><p className="eyebrow">Numbers you need to know</p><h3 className="mt-1 text-2xl font-semibold">A number is useful only with context</h3></section><div className="grid gap-4 md:grid-cols-2">{[['₹1,000 crore','Main BL→ML asset-size threshold','Non-deposit taking NBFCs, subject to category and group tests','Registration/SBR paragraphs 10, 11, 15 and 17–23'],['₹1,00,000 crore','Separate UL asset reference in the indexed July 2026 copy','Covered NBFCs, with RBI identification/transition provisions to be checked','Registration/SBR paragraphs 12, 24 and 27'],['15%','General ML+ CRAR minimum','Covered ML/UL NBFCs under the capital direction','Capital Adequacy paragraph 6(3)'],['>90 days','General NPA overdue test','Covered credit assets, with BL transition/product rules checked','IRACP paragraphs 43–44, 51 and 56']].map(([value,what,who,source])=><div key={value} className="rounded-2xl border border-border p-5"><p className="text-3xl font-semibold text-primary">{value}</p><p className="mt-2 font-semibold">{what}</p><p className="mt-2 text-sm leading-6 text-muted-foreground">Who: {who}</p><p className="mt-3 border-t border-border pt-3 text-xs font-semibold leading-5">Source: {source}</p></div>)}</div></>}
          {step === 'exceptions' && <><section><p className="eyebrow">Where the general rule changes</p><h3 className="mt-1 text-2xl font-semibold">Never stop at the headline rule</h3></section><div className="space-y-3">{[['Category placement','P2P, Account Aggregator and other specialist categories can be placed by category rather than the ordinary size route.'],['Group aggregation','Assets of registered NBFCs under common control can affect the layer test.'],['Public funds / customer interface','Some directions modify or exclude treatment based on these characteristics.'],['Specialist direction','A product or category-specific direction can be more specific than the general SBR consequence.'],['Transition','A threshold crossing, UL identification or amended provision may allow a stated implementation period.']].map(([title,body],index)=><div key={title} className="flex gap-4 rounded-2xl border border-border p-4"><span className="grid size-9 shrink-0 place-items-center rounded-xl bg-primary/10 font-mono text-xs font-semibold text-primary">{String(index+1).padStart(2,'0')}</span><div><p className="font-semibold">{title}</p><p className="mt-1 text-sm leading-6 text-muted-foreground">{body}</p></div></div>)}</div></>}
          {step === 'evolution' && <><section><p className="eyebrow">How did the framework evolve?</p><h3 className="mt-1 text-2xl font-semibold">Read the current position, but understand the route</h3></section><div className="space-y-4">{[['22 Oct 2021','RBI issued the Scale Based Regulation framework for NBFCs, introducing the four-layer approach.'],['01 Oct 2022','Key parts of the SBR framework became effective, subject to the implementation schedule.'],['28 Nov 2025','The indexed library reflects the 2025 consolidated Registration/SBR Direction.'],['01 Jul 2026','The folder copy of Registration/SBR is consolidated to this date and is used for this page.']].map(([date,body],index)=><div key={date} className="grid gap-3 rounded-2xl border border-border p-5 md:grid-cols-[150px_1fr]"><div><Badge variant={index===3?'default':'outline'}>{index===3?'CURRENT INDEXED COPY':date}</Badge></div><p className="text-sm leading-6">{body}</p></div>)}</div><aside className="rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm leading-6 text-amber-950">Before a filing or formal opinion, recheck the RBI website for any later amendment, circular, FAQ or supervisory instruction.</aside></>}
          {step === 'case' && <><section><p className="eyebrow">Practical case study</p><h3 className="mt-1 text-2xl font-semibold">ABC Finance Private Limited</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">NBFC-ICC · non-deposit taking · customer-facing · illustrative assets ₹1,250 crore.</p></section><div className="space-y-3">{[['1. Which layer should be examined?','ML, because the illustrative standalone asset size exceeds ₹1,000 crore—subject to confirming audited/group assets and the indexed classification provision.'],['2. What becomes relevant?','ML capital, IRACP, concentration, ALM, governance, conduct, KYC and reporting directions, each through its own applicability clause.'],['3. What remains conditional?','Product rules, LCR staging, specialist activities, public funds and thresholds that need additional facts.'],['4. What is the evidence trail?','Audited asset data, group map, CoR/category, Board classification paper and paragraph-by-paragraph applicability register.']].map(([question,answer])=><details key={question} className="rounded-2xl border border-border p-5"><summary className="cursor-pointer font-semibold">{question}</summary><p className="mt-3 text-sm leading-7 text-muted-foreground">{answer}</p></details>)}</div></>}
          {step === 'revise' && <><section><p className="eyebrow">SBR at a glance</p><h3 className="mt-1 text-2xl font-semibold">One-page revision view</h3></section><div className="grid gap-3 md:grid-cols-2">{[['Purpose','Increase regulatory intensity with size, complexity, activity and risk.'],['Covered entities','NBFCs within the direction, subject to category placement and exclusions.'],['Four layers','BL → ML → UL → exceptional TL.'],['Classification','Use asset size, deposit status, category, group aggregation and RBI identification.'],['Research method','Applicability → definition → operative rule → trigger → exception → date → source.'],['Current indexed position','Registration/SBR copy consolidated to 01 July 2026.']].map(([title,body])=><div key={title} className="rounded-2xl border border-border bg-secondary/25 p-4"><p className="font-semibold text-primary">{title}</p><p className="mt-2 text-sm leading-6">{body}</p></div>)}</div></>}
          {step === 'sources' && <><section><p className="eyebrow">Verify the law</p><h3 className="mt-1 text-2xl font-semibold">Authoritative-source centre</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Use the RBI source, not this explanation, for filing, approval or formal advice.</p></section><div className="space-y-3">{[['Primary regulatory source','RBI (NBFC – Registration, Exemptions and Framework for Scale Based Regulation) Directions, 2025','Indexed copy consolidated to 01 Jul 2026'],['Related prudential sources','Capital Adequacy; IRACP; Concentration Risk; ALM directions','Indexed copies dated 28 Nov 2025'],['Related governance / conduct','Governance; Responsible Business Conduct; Disclosures','Indexed copies dated 28 Nov 2025'],['Amendments / clarifications','Later RBI amendment directions, circulars, notifications and FAQs','Must be checked on RBI before reliance']].map(([kind,title,status])=><div key={kind} className="grid gap-2 rounded-2xl border border-border p-5 md:grid-cols-[190px_1fr_220px]"><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">{kind}</p><p className="font-semibold">{title}</p><p className="text-sm text-primary">{status}</p></div>)}</div><div className="flex flex-wrap gap-3"><a href={registrationSecondAmendmentUrl} target="_blank" rel="noreferrer"><Button>View RBI Second Amendment<ArrowRight /></Button></a>{regulations[0] && <Button variant="outline" onClick={() => openRegulation(regulations[0])}>Open indexed SBR note<BookOpen /></Button>}</div></>}
          <footer className="flex flex-col gap-4 border-t border-border pt-6 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs leading-5 text-muted-foreground">Regulatory study aid. Verify the latest RBI text, exact applicability paragraph and amendments before reliance.</p><div className="flex gap-2"><Button variant="outline" disabled={studySteps.findIndex(([key])=>key===step)===0} onClick={() => { const index=studySteps.findIndex(([key])=>key===step); setStep(studySteps[Math.max(0,index-1)][0]); }}>Previous</Button><Button disabled={studySteps.findIndex(([key])=>key===step)===studySteps.length-1} onClick={() => { const index=studySteps.findIndex(([key])=>key===step); setStep(studySteps[Math.min(studySteps.length-1,index+1)][0]); }}>Next<ArrowRight /></Button></div></footer>
        </div>
      </article>
    </div>}

    {view === 'regulation' && selectedRegulation && selectedDetail && <div className="overflow-hidden rounded-3xl border border-border bg-card">
      <header className="bg-[#07182b] p-6 text-white sm:p-9">
        <button type="button" onClick={() => setView('library')} className="inline-flex items-center gap-2 text-sm font-semibold text-cyan-200 hover:underline">← Back to master library</button>
        <div className="mt-6 flex flex-wrap items-center gap-2"><Badge className="bg-cyan-200 text-slate-950">{selectedRegulation.status}</Badge><Badge variant="outline" className="border-white/20 text-white">{selectedRegulation.category}</Badge><span className="text-sm text-slate-300">Indexed source copy: {selectedRegulation.updated}</span></div>
        <h2 className="mt-4 max-w-4xl text-3xl font-semibold leading-tight tracking-[-.04em] sm:text-4xl">{selectedRegulation.title}</h2>
        <p className="mt-4 max-w-4xl text-lg leading-8 text-slate-200">{selectedRegulation.summary}</p>
        <div className="mt-6 flex flex-wrap gap-2"><LayerBadges layers={selectedRegulation.layers} />{selectedRegulation.id === 1 && <><Button size="sm" className="ml-1 bg-cyan-200 text-slate-950 hover:bg-cyan-100" onClick={() => openStudy()}>Open complete SBR study<ArrowRight /></Button><a href={registrationSecondAmendmentUrl} target="_blank" rel="noreferrer"><Button size="sm" variant="outline" className="border-white/30 bg-white/5 text-white hover:bg-white/10">View RBI notification<ArrowRight /></Button></a></>}</div>
      </header>
      <div className="grid xl:grid-cols-[250px_minmax(0,1fr)]">
        <aside className="border-b border-border bg-secondary/20 p-4 xl:border-b-0 xl:border-r">
          <p className="eyebrow px-2">Learn this regulation</p>
          <div className="mt-3 grid gap-1 sm:grid-cols-5 xl:grid-cols-1">{(selectedRegulation.id === 1 ? [['meaning','Begin here'],['applicability','Layers & applicability'],['rules','All 15 chapters'],['example','Worked examples'],['source','Source & amendments']] : [['meaning','Start from zero'],['applicability','Who does it apply to?'],['rules','What does it require?'],['example','See an example'],['source','Verify the source']] as const).map(([key,label],index)=><button type="button" key={key} onClick={()=>setDetailSection(key as typeof detailSection)} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold ${detailSection===key?'bg-primary text-primary-foreground':'hover:bg-background'}`}><span className="font-mono text-xs opacity-70">0{index+1}</span>{label}</button>)}</div>
        </aside>
        <div className="min-w-0 space-y-8 p-6 sm:p-9">
          {selectedRegulation.id === 1 && detailSection === 'meaning' && <>
            <section><p className="eyebrow">Start from zero</p><h3 className="mt-1 text-2xl font-semibold">What does this Direction actually do?</h3><p className="mt-4 text-lg leading-8">It is the gateway to the NBFC regulatory system. It answers three questions in order: <strong>is the company carrying on NBFC business, must it register with RBI, and which SBR layer applies?</strong> Once those questions are answered, the NBFC opens the subject-specific directions for capital, KYC, conduct, governance and other operating rules.</p></section>
            <div className="grid gap-4 md:grid-cols-2"><section className="rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="font-semibold text-blue-950">Regulation identity</p><p className="mt-2 text-sm leading-7 text-blue-950">Reserve Bank of India (Non-Banking Financial Companies – Registration, Exemptions and Framework for Scale Based Regulation) Directions, 2025.</p><p className="mt-3 text-xs font-semibold leading-5 text-blue-900">RBI/DOR/2025-26/339 · DOR.FIN.REC.No.258/03.10.119/2025-26 · issued 28 November 2025</p></section><section className="rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><p className="font-semibold text-emerald-950">Version you are studying</p><p className="mt-2 text-sm leading-7 text-emerald-950">The supplied consolidated copy is marked “Updated as on July 01, 2026”. Check this cover-page marker before citing a paragraph, because a later consolidation may change numbering or the current position.</p></section></div>
            <section><p className="eyebrow">Learn it as five ordinary questions</p><div className="mt-4 space-y-3">{[
              ['1','Is this company really an NBFC?','Look at what the company actually does. If more than half of its assets are financial assets and more than half of its income comes from those assets, the 50–50 principal-business test is met. Both parts must be satisfied.','Paragraphs 37–38'],
              ['2','Does it need RBI registration?','Usually yes, once NBFC business is the company’s principal business. Then check the narrow statutory exemptions and the special Type I route for an entity with no public funds and no customer interface.','Paragraph 38A; Chapter IV'],
              ['3','What kind of NBFC is it?','Identify its legal category—such as ICC, MFI, Factor, P2P, AA, HFC, CIC or IFC—because category can decide both the rulebook and the minimum layer.','Paragraphs 4, 6 and 15'],
              ['4','Which layer is it in?','Use deposit status, category, audited assets, group assets and any RBI identification. The result is Base, Middle, Upper or, exceptionally, Top Layer.','Paragraphs 8–31'],
              ['5','Which operating rules apply next?','This Direction opens the door; it does not contain every capital, KYC or conduct rule. After classification, open each relevant subject Master Direction and read its own applicability clause.','Paragraphs 5 and 32–36A'],
            ].map(([number,question,answer,source])=><article key={number} className="grid gap-3 rounded-2xl border border-border p-5 md:grid-cols-[48px_1fr]"><span className="grid size-10 place-items-center rounded-full bg-primary/10 font-mono text-sm font-bold text-primary">{number}</span><div><h4 className="text-lg font-semibold">{question}</h4><p className="mt-2 text-sm leading-7 text-muted-foreground">{answer}</p><p className="mt-2 text-sm font-semibold text-primary">Read: {source}</p></div></article>)}</div></section>
            <section><p className="eyebrow">Words a beginner must know</p><h3 className="mt-1 text-xl font-semibold">Open a term whenever the legal language gets in the way</h3><div className="mt-4 grid gap-3 md:grid-cols-2">{registrationDefinitions.map(([term,meaning,source])=><details key={term} className="rounded-2xl border border-border p-4 open:border-primary/30 open:bg-secondary/20"><summary className="cursor-pointer font-semibold">{term}</summary><p className="mt-3 text-sm leading-7 text-muted-foreground">{meaning}</p><p className="mt-2 text-xs font-semibold text-primary">{source}</p></details>)}</div><p className="mt-4 text-sm leading-6 text-muted-foreground">If this Direction does not define a term, paragraph 7 sends you first to the RBI Act, then the Factoring Regulation Act, and then the Companies Acts.</p></section>
            <section className="rounded-2xl border border-border bg-secondary/25 p-5"><p className="font-semibold">Legal basis</p><p className="mt-2 text-sm leading-7 text-muted-foreground">The Direction invokes sections 45JA, 45K, 45L, 45M and 45NC of the RBI Act, 1934; the relevant Factoring Regulation Act, 2011 powers; and sections 30, 30A, 32 and 33 of the National Housing Bank Act, 1987. It commences when placed on RBI’s website, not merely by the issue date.</p><p className="mt-3 text-sm font-semibold text-primary">Preamble; paragraphs 1–2 and 72</p></section>
          </>}
          {selectedRegulation.id === 1 && detailSection === 'applicability' && <>
            <section><p className="eyebrow">Applicability first</p><h3 className="mt-1 text-2xl font-semibold">Who must use this Direction?</h3><p className="mt-4 text-base leading-8">Chapter IV has the specific scope stated in paragraph 3(1). The remaining provisions apply to RBI-registered NBFCs according to their SBR layer, including Government-company NBFCs. Entity-specific Master Directions in paragraph 4 apply <strong>in addition to</strong>, not instead of, this framework. Paragraph 5 points to 25 further Master Directions that must each be tested on their own terms.</p><p className="mt-3 text-sm font-semibold text-primary">Paragraphs 3–5</p></section>
            <section className="rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="font-semibold text-blue-950">Do not choose a layer from asset size alone</p><p className="mt-2 text-sm leading-7 text-blue-950">Ask these questions in order: Is it deposit-taking? What NBFC category appears on the CoR? What are the latest audited standalone assets? Is it part of a group containing other NBFCs? Is it a bank-group entity? Has RBI separately identified it?</p><div className="mt-4 grid gap-2 sm:grid-cols-2">{['Deposit-taking status','Exact CoR category','Latest audited assets','Assets of related NBFCs','Public funds and customer interface','Any RBI or bank-group overlay'].map((item)=><div key={item} className="flex gap-2 rounded-xl bg-white/70 p-3 text-sm font-medium text-blue-950"><CheckCircle2 className="mt-0.5 size-4 shrink-0 text-blue-700" />{item}</div>)}</div></section>
            <section><p className="eyebrow">Category can override size</p><div className="mt-4 overflow-x-auto rounded-2xl border border-border"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-[#07182b] text-white"><tr><th className="p-4">Category</th><th className="p-4">Starting layer</th><th className="p-4">Beginner explanation</th><th className="p-4">Source</th></tr></thead><tbody>{[
              ['P2P · AA · NOFHC · registered Type I','Always BL','These categories remain in Base Layer even if their asset size is high.','Paragraph 15(1)'],
              ['NBFC-D','At least ML','A deposit-taking NBFC can never be Base Layer, however small it is.','Paragraphs 11 and 15(2)'],
              ['SPD · IDF-NBFC','Always ML','These specialist categories remain in Middle Layer.','Paragraph 15(2)'],
              ['CIC · HFC · NBFC-IFC','ML or UL','They begin in Middle Layer and can move to Upper Layer if the UL test is met.','Paragraph 15(2)'],
              ['ICC · MFI · Factor · MGC','BL, ML or UL','Their result depends on size, group consolidation and the SBR parameters.','Paragraph 15(3)'],
            ].map((row)=><tr key={row[0]} className="border-t border-border align-top"><td className="p-4 font-semibold">{row[0]}</td><td className="p-4 font-semibold text-primary">{row[1]}</td><td className="p-4 leading-6">{row[2]}</td><td className="p-4 text-primary">{row[3]}</td></tr>)}</tbody></table></div></section>
            <section><div><p className="eyebrow">Four layers</p><h3 className="mt-1 text-xl font-semibold">What each layer means and what changes</h3></div><div className="mt-5 grid gap-4 xl:grid-cols-2">{registrationLayerRows.map((row)=><article key={row.code} className="overflow-hidden rounded-2xl border border-blue-200"><div className="flex items-center justify-between bg-blue-950 px-5 py-4 text-white"><div><p className="text-xs font-semibold uppercase tracking-[.12em] text-blue-200">{row.code}</p><p className="mt-1 text-lg font-semibold">{row.name}</p></div><span className="grid size-10 place-items-center rounded-full bg-white/10 font-mono text-sm font-bold">{row.code}</span></div><div className="space-y-4 p-5"><div><p className="text-xs font-semibold uppercase tracking-[.08em] text-muted-foreground">Who falls here</p><p className="mt-1 text-sm leading-7">{row.who}</p></div><div><p className="text-xs font-semibold uppercase tracking-[.08em] text-muted-foreground">What changes</p><p className="mt-1 text-sm leading-7">{row.stricter}</p></div><div><p className="text-xs font-semibold uppercase tracking-[.08em] text-muted-foreground">Movement / exit</p><p className="mt-1 text-sm leading-7">{row.exit}</p></div><p className="border-t border-border pt-3 text-sm font-semibold text-primary">{row.source}</p></div></article>)}</div></section>
            <section className="rounded-2xl border border-amber-200 bg-amber-50 p-5"><p className="font-semibold text-amber-950">Cascading-upward principle</p><p className="mt-2 text-sm leading-7 text-amber-950">Lower-layer rules generally extend upward unless the relevant direction says otherwise. ML adds to BL; UL adds to ML; TL adds institution-specific capital and supervision. A bank-group NBFC may also have to apply the Commercial Banks financial-services rules to overlapping activities without changing its formal SBR layer.</p><p className="mt-3 text-sm font-semibold text-amber-900">Paragraphs 32–36A</p></section>
            <section><p className="eyebrow">What happens when a threshold changes?</p><div className="mt-4 grid gap-3 md:grid-cols-3">{[
              ['Crossing ₹1,000 crore','Middle Layer requirements apply using the latest balance-sheet position; temporary monthly fluctuation does not permit an immediate step-down.','Paragraphs 22–23'],
              ['Entering Upper Layer','Within three months the Board adopts the implementation policy; full compliance follows within the overall 24-month period.','Paragraph 27'],
              ['Leaving Upper Layer','The enhanced framework normally continues for at least five years. The voluntary strategic-reduction exception is narrow.','Paragraphs 28–29'],
            ].map(([title,body,source])=><article key={title} className="rounded-2xl border border-border p-5"><h4 className="font-semibold">{title}</h4><p className="mt-2 text-sm leading-7 text-muted-foreground">{body}</p><p className="mt-3 text-sm font-semibold text-primary">{source}</p></article>)}</div></section>
          </>}
          {selectedRegulation.id === 1 && detailSection === 'rules' && <>
            <section><p className="eyebrow">The complete Direction in plain English</p><h3 className="mt-1 text-2xl font-semibold">Fifteen connected chapters</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Read from 01 to 15 for the full story, or open the chapter matching your question. Each chapter explains what the rule means, why it matters and where it appears.</p><div className="mt-5 space-y-3">{registrationChapters.map((chapter,index)=><details key={chapter.title} className="rounded-2xl border border-border p-5 open:border-primary/25 open:bg-secondary/20"><summary className="flex cursor-pointer list-none items-center gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-primary/10 font-mono text-xs font-semibold text-primary">{String(index+1).padStart(2,'0')}</span><span className="font-semibold">{chapter.title}</span><ChevronRight className="ml-auto size-4" /></summary><p className="mt-4 text-base leading-7">{chapter.plain}</p><ul className="mt-4 space-y-2">{chapter.points.map((point)=><li key={point} className="flex gap-2 text-sm leading-7 text-muted-foreground"><CheckCircle2 className="mt-1.5 size-4 shrink-0 text-primary" />{point}</li>)}</ul><p className="mt-4 border-t border-border pt-3 text-sm font-semibold text-primary">Read: {chapter.source}</p></details>)}</div></section>
            <section><p className="eyebrow">Type I or Type II?</p><h3 className="mt-1 text-xl font-semibold">Follow this decision route</h3><div className="mt-4 space-y-3">{[
              ['1. Test the business model','Confirm both no public funds and no customer interface—and no intention to have either. If either condition fails, the entity needs the Type II route.'],
              ['2. Check audited asset size','Below ₹1,000 crore may qualify for the paragraph 65A exemption. At ₹1,000 crore or more, apply for Type I registration.'],
              ['3. Prepare the evidence','Use PRAVAAH and supply the prescribed CoR, three years of audited financials, status statement, auditor certificate and Board resolutions or undertakings.'],
              ['4. Keep proving the condition','Notes to Accounts must disclose the status. The statutory auditor files an exception report if a condition is breached.'],
              ['5. Register before changing the model','Before taking public funds or creating customer interface, obtain Type II registration. Do not change first and regularise later.'],
              ['6. Check overseas investment separately','An Unregistered Type I NBFC intending financial-services investment overseas must register and obtain the applicable prior approval; non-financial overseas investment is not permitted under this route.'],
            ].map(([title,body])=><article key={title} className="rounded-2xl border border-border p-5"><h4 className="font-semibold">{title}</h4><p className="mt-2 text-sm leading-7 text-muted-foreground">{body}</p></article>)}</div><p className="mt-4 text-sm font-semibold text-primary">Paragraph 38A and paragraph 65A · initial application window for eligible existing entities: by 31 December 2026</p></section>
            <section><p className="eyebrow">This Direction is only the gateway</p><h3 className="mt-1 text-xl font-semibold">Specialist categories also open their own rulebook</h3><div className="mt-4 grid gap-3 md:grid-cols-2">{registrationRulebooks.map(([category,direction])=><article key={category} className="rounded-xl border border-border p-4"><p className="font-semibold">{category}</p><p className="mt-1 text-sm leading-6 text-muted-foreground">{direction}</p></article>)}</div><details className="mt-4 rounded-2xl border border-border p-5"><summary className="cursor-pointer font-semibold">See the 25 cross-cutting directions identified in paragraph 5</summary><p className="mt-3 text-sm leading-7 text-muted-foreground">Branch Authorisation; Undertaking of Financial Services; Acquisition of Shareholding or Control; Governance; Responsible Business Conduct; Voluntary Amalgamation; Miscellaneous; Capital Adequacy; Climate Finance and Climate Risk; Credit Risk Management; Credit Facilities; Concentration Risk; Transfer and Distribution of Credit Risk; Securitisation; Income Recognition, Asset Classification and Provisioning; Resolution of Stressed Assets; Wilful and Large Defaulters; Investment Portfolio; Asset Liability Management; Outsourcing; Financial Statements and Disclosures; Dividend Prudential Norms; Credit Information Reporting; KYC; and Credit Cards.</p></details></section>
            <section><p className="eyebrow">Numbers that decide the answer</p><div className="mt-4 overflow-x-auto rounded-2xl border border-border"><table className="w-full min-w-[820px] text-left text-sm"><thead className="bg-[#07182b] text-white"><tr><th className="p-4">Value</th><th className="p-4">What it controls</th><th className="p-4">Condition</th><th className="p-4">Source</th></tr></thead><tbody>{registrationNumbers.map((row)=><tr key={row[0]+row[1]} className="border-t border-border align-top"><td className="p-4 text-base font-semibold text-primary">{row[0]}</td><td className="p-4 font-semibold">{row[1]}</td><td className="p-4 leading-6">{row[2]}</td><td className="p-4 font-semibold text-primary">{row[3]}</td></tr>)}</tbody></table></div></section>
            <section><p className="eyebrow">Exemptions are section-specific</p><h3 className="mt-1 text-xl font-semibold">“Exempt” does not mean “outside every law”</h3><p className="mt-2 text-sm leading-7 text-muted-foreground">Read the exact RBI Act sections removed for the entity and the conditions attached. Never infer a general exemption merely because another regulator also supervises the entity.</p><div className="mt-4 overflow-x-auto rounded-2xl border border-border"><table className="w-full min-w-[880px] text-left text-sm"><thead className="bg-[#07182b] text-white"><tr><th className="p-4">Exemption</th><th className="p-4">Who may use it</th><th className="p-4">Paragraph</th></tr></thead><tbody>{registrationExemptions.map((row)=><tr key={row[0]+row[2]} className="border-t border-border align-top"><td className="p-4 font-semibold text-primary">{row[0]}</td><td className="p-4 leading-7">{row[1]}</td><td className="p-4 font-semibold">{row[2]}</td></tr>)}</tbody></table></div></section>
          </>}
          {selectedRegulation.id === 1 && detailSection === 'example' && <>
            <section><p className="eyebrow">Example 1 · Are you an NBFC?</p><h3 className="mt-1 text-2xl font-semibold">Both halves of the 50–50 test must pass</h3><div className="mt-4 grid gap-3 md:grid-cols-2"><article className="rounded-2xl border border-border p-5"><p className="text-sm font-semibold text-muted-foreground">Financial assets</p><p className="mt-2 text-2xl font-semibold text-primary">58% of total assets</p><p className="mt-2 text-sm leading-6">The first limb passes because financial assets exceed 50%.</p></article><article className="rounded-2xl border border-border p-5"><p className="text-sm font-semibold text-muted-foreground">Financial income</p><p className="mt-2 text-2xl font-semibold text-primary">46% of gross income</p><p className="mt-2 text-sm leading-6">The second limb fails because financial income does not exceed 50%.</p></article></div><p className="mt-4 rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm leading-7 text-amber-950"><strong>Conclusion:</strong> the company does not satisfy the principal-business test on these figures. Passing only one limb is not enough. Reassess using the latest audited balance sheet. <span className="font-semibold">Paragraph 38.</span></p></section>
            <section><p className="eyebrow">Worked group example</p><h3 className="mt-1 text-2xl font-semibold">Why a small NBFC can still become Middle Layer</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Based on the worked method described around paragraph 19 in the supplied reference.</p></section>
            <div className="overflow-x-auto rounded-2xl border border-border"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-[#07182b] text-white"><tr><th className="p-4">Group entity</th><th className="p-4">Assets</th><th className="p-4">Standalone position</th><th className="p-4">After consolidation</th></tr></thead><tbody>{[['NBFC-ICC','₹300 cr','BL','ML'],['HFC','₹300 cr','ML','ML'],['NBFC-IFC','₹500 cr','ML','ML'],['NBFC-MFI','₹100 cr','BL','ML'],['NBFC-P2P','₹50 cr','Always BL','BL'],['Type I NBFC','₹70 cr','Always BL','BL']].map((row)=><tr key={row[0]} className="border-t border-border"><td className="p-4 font-semibold">{row[0]}</td><td className="p-4">{row[1]}</td><td className="p-4">{row[2]}</td><td className="p-4 font-semibold text-primary">{row[3]}</td></tr>)}</tbody></table></div>
            <section className="rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="font-semibold text-blue-950">Calculation and conclusion</p><p className="mt-2 text-sm leading-7 text-blue-950">Group assets total <strong>₹1,320 crore</strong>, exceeding the ₹1,000 crore ML boundary. Therefore the ICC and MFI are pulled into ML. The HFC and IFC remain ML. P2P and Type I remain BL because paragraph 15(1)’s activity/category placement overrides the group result.</p><p className="mt-3 text-sm font-semibold text-blue-900">Paragraphs 17–20; group certification is required annually as at 31 March.</p></section>
            <section className="rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><p className="font-semibold text-emerald-950">The same result can occur even when one entity is tiny</p><p className="mt-2 text-sm leading-7 text-emerald-950">If the ICC in this example had assets of only ₹10 crore, the group total would still be ₹1,030 crore. The group still crosses the threshold, so the ICC and MFI still move to Middle Layer. The test looks at the group total, not whether each affected entity is individually large.</p></section>
            <section><p className="eyebrow">Example 3 · Type I decision</p><div className="mt-4 grid gap-3 md:grid-cols-3">{[
              ['Company A','No public funds · no customer interface · ₹600 crore','May examine the paragraph 65A exemption and deregistration route, subject to every condition.'],
              ['Company B','No public funds · no customer interface · ₹1,200 crore','Must apply for Type I registration because audited assets are ₹1,000 crore or more.'],
              ['Company C','No public funds today · plans retail customers','Cannot rely on the Type I model; it must obtain Type II registration before creating customer interface.'],
            ].map(([name,facts,result])=><article key={name} className="rounded-2xl border border-border p-5"><p className="font-semibold">{name}</p><p className="mt-2 text-sm leading-6 text-muted-foreground">{facts}</p><p className="mt-4 border-t border-border pt-3 text-sm font-semibold leading-6 text-primary">{result}</p></article>)}</div><p className="mt-4 text-sm font-semibold text-primary">Paragraph 38A and paragraph 65A</p></section>
            <section><p className="eyebrow">Apply the same method</p><div className="mt-4 grid gap-3 md:grid-cols-2">{['List every CoR-holding NBFC in the group','Map the paragraph 6 group links','Add assets for the ML threshold test','Apply category-fixed placements','Record each entity’s resulting layer','Obtain the statutory-auditor certification'].map((item,index)=><div key={item} className="flex gap-3 rounded-xl border border-border p-4 text-sm leading-6"><span className="font-mono text-xs font-semibold text-primary">0{index+1}</span>{item}</div>)}</div></section>
          </>}
          {selectedRegulation.id === 1 && detailSection === 'source' && <>
            <section><p className="eyebrow">Verify the source</p><h3 className="mt-1 text-2xl font-semibold">Identity, version and amendment history</h3></section>
            <div className="grid gap-4 md:grid-cols-2"><section className="rounded-2xl border border-border p-5"><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">Primary source</p><p className="mt-3 font-semibold leading-7">RBI NBFC Registration, Exemptions and Framework for Scale Based Regulation Directions, 2025</p><p className="mt-3 text-sm leading-6 text-muted-foreground">Notification RBI/DOR/2025-26/339 · issued 28 Nov 2025 · supplied copy updated as on 01 Jul 2026.</p></section><section className="rounded-2xl border border-border p-5"><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">How to verify currency</p><ol className="mt-3 space-y-2 text-sm leading-6"><li>1. Check the cover-page “Updated as on” date.</li><li>2. Review amendment footnotes throughout the Direction.</li><li>3. Compare with RBI’s live Master Directions page and related FAQs.</li></ol></section></div>
            <section><p className="eyebrow">Amendment timeline</p><div className="mt-4 space-y-3">{[['28 Nov 2025','Base Direction issued.'],['29 Apr 2026 · effective 01 Jul 2026','Created the Type I / Type II regime, paragraph 38A process and paragraph 65A exemption.'],['24 Jun 2026','Second Amendment replaced the earlier UL scorecard with the ₹1,00,000 crore asset threshold, deleted superseded provisions and inserted the bank-group rule in paragraph 36A.'],['01 Jul 2026','Version marker on the supplied consolidated copy.']].map(([date,body],index)=><div key={date} className="grid gap-2 rounded-2xl border border-border p-5 md:grid-cols-[220px_1fr]"><div><Badge variant={index===3?'default':'outline'}>{date}</Badge></div><p className="text-sm leading-7">{body}</p></div>)}</div></section>
            <section className="rounded-2xl border border-amber-200 bg-amber-50 p-5"><div className="flex gap-3"><AlertTriangle className="mt-1 size-5 shrink-0 text-amber-700" /><div><p className="font-semibold text-amber-950">Before formal reliance</p><p className="mt-2 text-sm leading-7 text-amber-950">Verify whether RBI has published a consolidation later than 1 July 2026. A later version can change both the substantive position and the paragraph numbers shown here.</p></div></div></section>
            <div className="flex flex-wrap gap-3"><a href={registrationSecondAmendmentUrl} target="_blank" rel="noreferrer"><Button>Open RBI Second Amendment notification<ArrowRight /></Button></a><Button variant="outline" onClick={()=>onOpenRegulation(selectedRegulation)}>Open compact indexed note<FileSearch /></Button></div>
          </>}
          {selectedRegulation.id !== 1 && detailSection === 'meaning' && <>
            <section><p className="eyebrow">What is this regulation?</p><h3 className="mt-1 text-2xl font-semibold">The idea in simple words</h3><p className="mt-4 text-lg leading-8">{selectedRegulation.summary}</p></section>
            <div className="grid gap-4 md:grid-cols-2"><section className="rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="font-semibold text-blue-950">Why does it exist?</p><p className="mt-2 text-sm leading-7 text-blue-950">{categoryPurpose[selectedRegulation.category] ?? 'It creates a consistent regulatory test for the activity and tells the NBFC what must be controlled, reported or evidenced.'}</p></section><section className="rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><p className="font-semibold text-emerald-950">When should I open it?</p><p className="mt-2 text-sm leading-7 text-emerald-950">{categoryTrigger[selectedRegulation.category] ?? 'Open it when the activity, transaction, event or reporting date described by the direction occurs.'}</p></section></div>
            <section><p className="eyebrow">The regulation in one flow</p><div className="mt-4 grid gap-3 md:grid-cols-4">{[['1','Profile','Confirm category, layer and operating model.'],['2','Trigger','Find the event or activity that activates the rule.'],['3','Rule','Read the obligation with threshold and exception.'],['4','Evidence','Record the conclusion and supporting source.']].map(([number,title,body])=><div key={number} className="rounded-2xl border border-border p-4"><span className="font-mono text-xs font-semibold text-primary">{number}</span><p className="mt-2 font-semibold">{title}</p><p className="mt-1 text-sm leading-6 text-muted-foreground">{body}</p></div>)}</div></section>
          </>}
          {selectedRegulation.id !== 1 && detailSection === 'applicability' && <>
            <section><p className="eyebrow">Applicability first</p><h3 className="mt-1 text-2xl font-semibold">Who must examine this direction?</h3><p className="mt-4 text-base leading-8">{selectedDetail.applies}</p></section>
            {layerGuide ? <section><div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow">Layer-by-layer position</p><h3 className="mt-1 text-xl font-semibold">BL, ML and UL separately</h3></div><p className="max-w-xl text-sm leading-6 text-muted-foreground">{layerGuide.scope}</p></div><div className="mt-5 grid gap-4 lg:grid-cols-3">{(['BL','ML','UL'] as const).map((code)=>{const rule=layerGuide.rules[code];return <article key={code} className="overflow-hidden rounded-2xl border border-blue-200"><div className="flex items-center justify-between bg-blue-950 px-5 py-4 text-white"><div><p className="text-xs font-semibold uppercase tracking-[.12em] text-blue-200">{code==='BL'?'Base Layer':code==='ML'?'Middle Layer':'Upper Layer'}</p><p className="mt-1 font-semibold">{rule.position}</p></div><span className="grid size-9 place-items-center rounded-full bg-white/10 font-mono text-sm font-bold">{code}</span></div><div className="p-5"><p className="text-sm leading-7">{rule.explanation}</p><div className="mt-4 rounded-xl bg-blue-50 p-3"><p className="text-xs font-semibold uppercase tracking-[.08em] text-blue-800">Paragraph / clause</p><p className="mt-1 text-sm font-semibold leading-6 text-blue-950">{rule.clause}</p></div></div></article>})}</div><p className="mt-4 text-sm leading-6"><strong>Primary source:</strong> {layerGuide.source}</p></section> : <aside className="rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm leading-7 text-amber-950">A verified layer-by-layer guide is not yet available. Do not infer applicability from the card badges alone.</aside>}
            <section className="rounded-2xl border border-border bg-secondary/25 p-5"><p className="font-semibold">Facts that can change the answer</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{['Exact NBFC category and CoR','BL / ML / UL classification','Deposit-taking status','Public funds and customer interface','Product or transaction involved','Threshold, exemption and transition date'].map((item)=><div key={item} className="flex gap-2 text-sm leading-6"><CheckCircle2 className="mt-1 size-4 shrink-0 text-primary" />{item}</div>)}</div></section>
          </>}
          {selectedRegulation.id !== 1 && detailSection === 'rules' && <>
            <section><p className="eyebrow">What does RBI require?</p><h3 className="mt-1 text-2xl font-semibold">The main rules in plain English</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Read each rule together with the applicability clause, trigger, threshold and any exception.</p><div className="mt-5 grid gap-3 md:grid-cols-2">{selectedDetail.requirements.map((item,index)=><div key={item} className="flex gap-3 rounded-2xl border border-border p-4"><span className="grid size-8 shrink-0 place-items-center rounded-xl bg-primary/10 font-mono text-xs font-semibold text-primary">{String(index+1).padStart(2,'0')}</span><p className="text-sm leading-7">{item}</p></div>)}</div></section>
            <section><p className="eyebrow">Numbers and deadlines</p><div className="mt-4 grid gap-3 md:grid-cols-2">{selectedRegulation.highlights.map((item)=><div key={item} className="rounded-xl bg-blue-50 p-4 text-sm font-semibold leading-6 text-blue-950">{item}</div>)}{selectedDetail.timing.map((item)=><div key={item} className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm leading-6 text-amber-950">{item}</div>)}</div></section>
          </>}
          {selectedRegulation.id !== 1 && detailSection === 'example' && <>
            <section><p className="eyebrow">A simple fictional example</p><h3 className="mt-1 text-2xl font-semibold">How the analysis works</h3></section>
            <div className="grid gap-4 lg:grid-cols-[.9fr_1.1fr]"><section className="rounded-2xl border border-border bg-secondary/25 p-5"><p className="font-semibold">ABC Finance Private Limited</p><ul className="mt-3 space-y-2 text-sm leading-6 text-muted-foreground"><li>NBFC-ICC</li><li>Non-deposit taking</li><li>Customer-facing</li><li>Assume ML for this illustration</li></ul></section><section className="rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="font-semibold text-blue-950">Question to answer</p><p className="mt-2 text-sm leading-7 text-blue-950">ABC Finance is considering an activity covered by <strong>{selectedRegulation.short}</strong>. It should first confirm that its category and ML profile fall within the applicability clause, identify the specific activity or event that triggers the rule, then test the operative requirements and exceptions. ML status is relevant, but it is not a substitute for reading the source clause.</p></section></div>
            <section><p className="eyebrow">What should the reviewer ask?</p><div className="mt-4 space-y-3">{selectedDetail.checks.map((item,index)=><div key={item} className="flex gap-3 rounded-xl border border-border p-4 text-sm leading-7"><span className="font-mono text-xs font-semibold text-primary">Q{index+1}</span>{item}</div>)}</div></section>
          </>}
          {selectedRegulation.id !== 1 && detailSection === 'source' && <>
            <section><p className="eyebrow">Verify the source</p><h3 className="mt-1 text-2xl font-semibold">Do not rely on the summary alone</h3></section>
            <div className="grid gap-4 md:grid-cols-2"><section className="rounded-2xl border border-border p-5"><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">Primary indexed source</p><p className="mt-3 font-semibold leading-7">{layerGuide?.source ?? selectedRegulation.title}</p><p className="mt-3 text-sm text-muted-foreground">Source copy indexed: {selectedRegulation.updated}</p></section><section className="rounded-2xl border border-border p-5"><p className="text-xs font-semibold uppercase tracking-[.1em] text-muted-foreground">Start with these paragraphs</p><p className="mt-3 text-sm font-semibold leading-7 text-primary">{layerGuide ? `BL: ${layerGuide.rules.BL.clause} · ML: ${layerGuide.rules.ML.clause} · UL: ${layerGuide.rules.UL.clause}` : 'Read the applicability clause and operative chapter in the indexed source.'}</p></section></div>
            <section className="rounded-2xl border border-amber-200 bg-amber-50 p-5"><div className="flex gap-3"><AlertTriangle className="mt-1 size-5 shrink-0 text-amber-700" /><div><p className="font-semibold text-amber-950">Current-law check</p><p className="mt-2 text-sm leading-7 text-amber-950">This desk explains the source copy stored in the uploaded library. Before filing, approving or issuing formal advice, check the RBI website for a later amendment, circular, FAQ, transition provision or supervisory communication.</p></div></div></section>
            <div className="flex flex-wrap gap-3"><a href="https://www.rbi.org.in/" target="_blank" rel="noreferrer"><Button>Open RBI official website<ArrowRight /></Button></a><Button variant="outline" onClick={()=>onOpenRegulation(selectedRegulation)}>Open full indexed detail sheet<FileSearch /></Button></div>
          </>}
          <footer className="flex flex-col gap-3 border-t border-border pt-6 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs leading-5 text-muted-foreground">Meaning → applicability → rule → example → source. Always conclude provision-by-provision.</p><div className="flex gap-2">{selectedDetail.related.slice(0,3).map((id)=>{const reg=regulations.find((item)=>item.id===id);return reg?<Button key={id} size="sm" variant="outline" onClick={()=>openRegulation(reg)}>{reg.short}<ChevronRight /></Button>:null})}</div></footer>
        </div>
      </div>
    </div>}

    {view === 'library' && <><div className="rounded-3xl border border-border bg-card p-5 sm:p-7"><div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="eyebrow">Master Regulatory Library</p><h2 className="mt-1 text-2xl font-semibold">{regulations.length} indexed regulations and reference sources</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-muted-foreground">Every card opens a beginner-first lesson: meaning, purpose, applicability, BL/ML/UL position, main rules, example and source paragraphs.</p></div><div className="grid gap-2 sm:grid-cols-[260px_150px]"><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input value={libraryQuery} onChange={(event)=>setLibraryQuery(event.target.value)} placeholder="Search the library" className="pl-9" /></div><NativeSelect value={libraryLayer} onChange={(event)=>setLibraryLayer(event.target.value)}>{['All','BL','ML','UL'].map((item)=><NativeSelectOption key={item} value={item}>{item==='All'?'All layers':item}</NativeSelectOption>)}</NativeSelect></div></div></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{library.map((regulation)=><button type="button" key={regulation.id} onClick={()=>openRegulation(regulation)} className="group rounded-2xl border border-border bg-card p-5 text-left hover:-translate-y-0.5 hover:border-primary/30 hover:shadow-sm"><div className="flex items-start justify-between gap-3"><span className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><FileSearch className="size-5" /></span><Badge variant="outline">{regulation.status}</Badge></div><h3 className="mt-4 text-lg font-semibold leading-6 group-hover:text-primary">{regulation.title}</h3><p className="mt-2 line-clamp-3 text-sm leading-6 text-muted-foreground">{regulation.summary}</p><div className="mt-4"><LayerBadges layers={regulation.layers} /></div><div className="mt-4 flex items-center justify-between border-t border-border pt-4"><span className="text-xs font-semibold text-muted-foreground">Source copy: {regulation.updated}</span><span className="inline-flex items-center gap-1 text-xs font-semibold text-primary">Learn this regulation<ChevronRight className="size-4" /></span></div></button>)}</div></>}
  </section>;
}
